// MineBench: Cho-Choo Train v33 - big driving wheels with connecting rods, trailing wheels
// Ground
for(var x=90;x<200;x++)for(var z=20;z<260;z++)
  block(x,0,z,Math.random()<0.15?'dirt':'grass_block');
// Track rails at x=112 and x=127, running in Z
for(var z=60;z<230;z++){block(112,1,z,'oak_log');block(127,1,z,'oak_log');
  for(var dx=113;dx<=126;dx++){block(dx,1,z,'dirt');block(dx,2,z,'gray_wool');}}
for(var z=60;z<230;z++)for(var dx=112;dx<=127;dx++)block(dx,0,z,'dirt');

// Driving wheels (r=9, w=5, black_wool, face=x, x=112/127, hub y=10)
var dwz=[130,150];
for(var i=0;i<2;i++)for(var s=0;s<5;s++)for(var a=-9;a<=9;a++)for(var b=-9;b<=9;b++){
  var d2=a*a+b*b;if(d2>81+9)continue;
  if(d2<49&&a!==0&&b!==0&&Math.abs(a)!==Math.abs(b))continue;
  block(112+s,10+b,dwz[i]+a,'black_wool');
  block(127+s,10+b,dwz[i]+a,'black_wool');
}
block(111,10,130,'iron_block');block(111,10,150,'iron_block');
block(126,10,130,'iron_block');block(126,10,150,'iron_block');

// Small front truck wheels (r=5, w=3, cobblestone, hub y=7)
for(var s=0;s<3;s++)for(var a=-5;a<=5;a++)for(var b=-5;b<=5;b++){
  var d2=a*a+b*b;if(d2>25+5)continue;
  if(d2<9&&a!==0&&b!==0&&Math.abs(a)!==Math.abs(b))continue;
  block(112+s,7+b,105+a,'cobblestone');
  block(127+s,7+b,105+a,'cobblestone');
}
// Small rear truck wheels (r=5, w=3, cobblestone)
for(var s=0;s<3;s++)for(var a=-5;a<=5;a++)for(var b=-5;b<=5;b++){
  var d2=a*a+b*b;if(d2>25+5)continue;
  if(d2<9&&a!==0&&b!==0&&Math.abs(a)!==Math.abs(b))continue;
  block(112+s,7+b,195+a,'cobblestone');
  block(127+s,7+b,195+a,'cobblestone');
}
// Trailing wheels under cab (r=5, w=3, cobblestone)
for(var s=0;s<3;s++)for(var a=-5;a<=5;a++)for(var b=-5;b<=5;b++){
  var d2=a*a+b*b;if(d2>25+5)continue;
  if(d2<9&&a!==0&&b!==0&&Math.abs(a)!==Math.abs(b))continue;
  block(112+s,7+b,175+a,'cobblestone');
  block(127+s,7+b,175+a,'cobblestone');
}

// Boiler
var bx=140,by=25,brx=12,bry=10;
for(var x=bx-brx;x<=bx+brx;x++)for(var y=by-bry;y<=by+bry;y++){
  if(((x-bx)*(x-bx))/(brx*brx)+((y-by)*(y-by))/(bry*bry)<=1)
    for(var z=100;z<=145;z++)block(x,y,z,'iron_block');
}

// Chassis
for(var z=80;z<=180;z++){block(110,4,z,'iron_block');block(125,4,z,'iron_block');
  block(110,5,z,'gray_wool');block(125,5,z,'gray_wool');}
for(var x=100;x<=180;x++){block(x,4,100,'gray_wool');block(x,4,120,'gray_wool');
  block(x,4,140,'gray_wool');block(x,4,160,'gray_wool');
  block(x,4,180,'gray_wool');}

// Boiler supports
for(var y=5;y<=24;y++){block(126,y,100,'iron_block');block(152,y,100,'iron_block');
  block(126,y,145,'iron_block');block(152,y,145,'iron_block');}

// Smokebox - cylindrical, matching boiler diameter
for(var z=145;z<=155;z++)for(var x=132;x<=148;x++)for(var y=18;y<=32;y++){
  var dx2=(x-140)*(x-140)/64,dy2=(y-25)*(y-25)/49;
  if(dx2+dy2<=1)block(x,y,z,'stone_bricks');
}
// Smokebox door face
for(var y=18;y<=32;y++)for(var x=132;x<=148;x++){
  var dx2=(x-140)*(x-140)/64,dy2=(y-25)*(y-25)/49;
  if(dx2+dy2<=1)block(x,y,155,'stone');
}
block(140,25,156,'glowstone');

// Cowcatcher
for(var z=155;z<=170;z++){var hw=Math.max(2,Math.round(8*(1-(z-155)/15)));
  for(var dx=-hw;dx<=hw;dx++)for(var dy=4;dy<=9;dy++)block(140+dx,dy,z,'stone');
  for(var dx=-hw;dx<=hw;dx++)for(var dy=4;dy<=9;dy++)block(140+dx,dy,z,'iron_block');}

// Connecting rod assembly
for(var x=104;x<=135;x++){block(x,18,133,'iron_block');block(x,18,134,'iron_block');}
for(var y=10;y<=18;y++){block(111,y,133,'iron_block');block(112,y,133,'iron_block');block(111,y,134,'iron_block');block(112,y,134,'iron_block');}
for(var x=104;x<=135;x++){block(x,18,125,'iron_block');block(x,18,126,'iron_block');}
for(var y=10;y<=18;y++){block(126,y,125,'iron_block');block(127,y,125,'iron_block');block(126,y,126,'iron_block');block(127,y,126,'iron_block');}
block(104,17,134,'iron_block');block(104,19,134,'iron_block');
block(104,17,126,'iron_block');block(104,19,126,'iron_block');

// Piston cylinder on boiler
for(var x=100;x<=104;x++)for(var y=16;y<=20;y++)for(var z=132;z<=136;z++)block(x,y,z,'iron_block');

// Chimney - sits on boiler top, centered at x=133
for(var y=34;y<=45;y++){block(132,y,124,'iron_block');block(134,y,124,'iron_block');
  block(132,y,126,'iron_block');block(134,y,126,'iron_block');
  block(133,y,125,'iron_block');}
for(var x=131;x<=135;x++)for(var z=123;z<=127;z++)block(x,45,z,'gold_block');

// Cab
for(var x=155;x<=185;x++)for(var y=5;y<=32;y++)for(var z=80;z<=110;z++)block(x,y,z,'oak_log');
for(var x=155;x<=185;x++){block(x,32,80,'bricks');block(x,32,110,'bricks');}
for(var dx=0;dx<=4;dx++){for(var x=155+dx;x<=185-dx;x++){
  block(x,33,80-dx,'bricks');block(x,33,110+dx,'bricks');
  block(x,34,80-dx,'bricks');block(x,34,110+dx,'bricks');}}

// Tender
for(var z=50;z<=80;z++)for(var x=186;x<=209;x++)for(var y=6;y<=19;y++)block(x,y,z,'oak_planks');
for(var z=50;z<=80;z++){for(var y=5;y<=30;y++){block(185,y,z,'oak_planks');}
  for(var y=21;y<=30;y++){block(210,y,z,'oak_planks');}}
for(var x=185;x<=210;x++)for(var z=50;z<=80;z++)block(x,20,z,'oak_planks');

// Water tower
for(var h=1;h<=50;h++){block(100,h,60,'oak_log');block(102,h,60,'oak_log');
  block(100,h,62,'oak_log');block(102,h,62,'oak_log');}
for(var x=92;x<=108;x++)for(var z=58;z<=64;z++)for(var y=50;y<=55;y++)block(x,y,z,'stone_bricks');
for(var x=94;x<=106;x++)for(var z=60;z<=62;z++)block(x,55,z,'oak_log');
for(var x=94;x<=106;x++)for(var z=60;z<=62;z++)block(x,56,z,'bricks');

// Dome solid base on boiler
for(var x=132;x<=138;x++)for(var y=15;y<=25;y++)for(var z=122;z<=126;z++)block(x,y,z,'iron_block');
for(var x=133;x<=137;x++)for(var y=26;y<=31;y++)for(var z=122;z<=126;z++){
  var dx2=(x-135)*(x-135)/4,dy2=(y-28)*(y-28)/9,dz2=(z-124)*(z-124)/4;
  if(dx2+dy2+dz2<=1)block(x,y,z,'gold_block');
}
